The extended spatial operator satisfies
\begin{equation}\label{PL1}
\mathscr{L}_{\varepsilon}
=
G^{-1}\mathscr{L}_0G.
\end{equation}
Moreover, the temporal operators satisfy
\begin{equation}\label{LP2}
G^{-1}\mathscr{M}_0G-G^{-1}G_t
=
\mathscr{M}_{\varepsilon}
-
\frac{\varepsilon}{2}\Theta[u,C]\,I,
\end{equation}
where
\[
\Theta[u,C]:=C_t-C_{xxx}-3uC_x.
\]

\label{prop:factorization-identities}
For arbitrary sufficiently smooth \(p\) and \(\eta\), the fields
defined by
\eqref{eq:factorization-u-fields} and
\eqref{eq:factorization-v-fields} satisfy
\begin{subequations}
\label{eq:factorization-identities}
\begin{align}
\mathcal{R}[u]
&=
-2\left(D_x+2p\right)E_p,
\label{eq:factorization-R-u}
\\
\mathcal{R}[\widetilde{u}]
&=
2\left(D_x-2p\right)E_p,
\label{eq:factorization-R-utilde}
\\
\mathcal{L}_u[v]
&=
-2\left[
\left(D_x+2p\right)E_{\eta}
+2\eta E_p
\right],
\label{eq:factorization-L-u}
\\
\mathcal{L}_{\widetilde{u}}[\widetilde{v}]
&=
2\left[
\left(D_x-2p\right)E_{\eta}
-2\eta E_p
\right].
\label{eq:factorization-L-utilde}
\end{align}
\end{subequations}

\label{lem:auxiliary-compatibility}
Let \((u,v)\) be a sufficiently smooth solution of the local
KdV--ghost system \eqref{eq:local-system-residue} and let \(p\) satisfy
\begin{subequations}
\label{eq:p-auxiliary-system}
\begin{align}
p_x
&=
\alpha-\frac{1}{2}u-p^2,
\label{eq:p-auxiliary-spatial}
\\
p_t
&=
\left[
-\frac{1}{2}u_x
+(4\alpha+u)p
\right]_x.
\label{eq:p-auxiliary-temporal}
\end{align}
\end{subequations}
Then the auxiliary system
\eqref{eq:eta-auxiliary-system} is compatible:
\begin{equation*}
\label{eq:eta-compatibility}
\partial_t(\eta_x)
=
\partial_x(\eta_t).
\end{equation*}

Moreover, if \(\eta_1\) and \(\eta_2\) are two solutions of
\eqref{eq:eta-auxiliary-system}, then their difference
\(
\rho:=\eta_1-\eta_2
\)
satisfies the homogeneous system
\begin{subequations}
\label{eq:eta-homogeneous-system}
\begin{align}
\rho_x
&=
-2p\rho,
\label{eq:rho-spatial}
\\
\rho_t
&=
\left[
(4\alpha+u)\rho
\right]_x.
\label{eq:rho-temporal}
\end{align}
\end{subequations}
